.ds-homepage img { max-width: 100%; height: auto; display: block; }
.ds-homepage a { color: #0066cc; text-decoration: none; }
.ds-homepage a:hover { text-decoration: underline; }
.ds-homepage .ds-container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }
.ds-homepage h1, .ds-homepage h2, .ds-homepage h3 { color: #111; margin-top: 0; margin-bottom: 1rem; line-height: 1.2; }
.ds-homepage .ds-section-title { text-align: center; font-size: clamp(2rem, 4vw, 2.5rem); margin-bottom: 3rem; }
.ds-homepage .ds-text-white { color: #fff !important; }
.ds-homepage .ds-btn { display: inline-block; padding: 0.75rem 1.5rem; border-radius: 4px; font-weight: 600; text-align: center; transition: all 0.2s ease; text-decoration: none !important; }
.ds-homepage .ds-btn-primary { background-color: #0066cc; color: #fff !important; border: 2px solid #0066cc; }
.ds-homepage .ds-btn-primary:hover { background-color: #004c99; border-color: #004c99; }
.ds-homepage .ds-btn-secondary { background-color: transparent; color: #0066cc !important; border: 2px solid #0066cc; }
.ds-homepage .ds-btn-secondary:hover { background-color: #f0f7ff; }
.ds-homepage .ds-btn-full { display: block; width: 100%; }
.ds-homepage .ds-header { padding: 1rem 0; border-bottom: 1px solid #eee; background: #fff; }
.ds-homepage .ds-header-inner { display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
.ds-homepage .ds-logo { font-size: 1.5rem; font-weight: 700; color: #0066cc; }
